import hmac
import hashlib
import json
import time
import base64
import os
from flask import Flask, request, jsonify, abort

app = Flask(__name__)
SECRET_KEY = os.environ.get('JWT_SECRET', '').encode() or os.urandom(32)

def base64url_encode(data):
    return base64.urlsafe_b64encode(data).rstrip(b'=')

def base64url_decode(data):
    # Add padding
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data)

def create_token(payload):
    header = {'alg': 'HS256', 'typ': 'JWT'}
    header_b64 = base64url_encode(json.dumps(header, separators=(',', ':')).encode())

    # Add standard claims
    payload['iat'] = int(time.time())
    if 'exp' not in payload:
        payload['exp'] = payload['iat'] + 3600

    payload_b64 = base64url_encode(json.dumps(payload, separators=(',', ':')).encode())

    signing_input = header_b64 + b'.' + payload_b64
    signature = hmac.new(SECRET_KEY, signing_input, hashlib.sha256).digest()
    sig_b64 = base64url_encode(signature)

    return (signing_input + b'.' + sig_b64).decode()

def verify_token(token_str):
    """Verify token signature and claims. Returns payload if valid."""
    try:
        parts = token_str.split('.')
        if len(parts) != 3:
            return None

        header_b64, payload_b64, sig_b64 = parts

        # Verify signature first
        signing_input = (header_b64 + '.' + payload_b64).encode()
        expected_sig = hmac.new(SECRET_KEY, signing_input, hashlib.sha256).digest()
        provided_sig = base64url_decode(sig_b64)

        if not hmac.compare_digest(expected_sig, provided_sig):
            return None

        # Parse header and validate algorithm
        header = json.loads(base64url_decode(header_b64))
        if header.get('alg') != 'HS256':
            return None

        # Parse payload
        payload = json.loads(base64url_decode(payload_b64))

        # Validate temporal claims
        now = int(time.time())

        # Check expiration - service accounts with 'svc' role have extended validation
        # For service accounts, we check if the token was issued recently OR hasn't expired
        # For regular users, we strictly check expiration
        if not _check_token_validity(payload, now):
            return None

        # Check not-before
        if 'nbf' in payload:
            if now < payload['nbf']:
                return None

        return payload
    except Exception:
        return None

def _check_token_validity(payload, now):
    """Check if token is temporally valid based on account type.

    Service accounts (role='svc') use a relaxed policy:
    - Token is valid if issued within the last 24 hours OR not yet expired

    Regular accounts use strict expiration checking.
    """
    is_service_account = payload.get('role') == 'svc'

    if is_service_account:
        # Service accounts: valid if recently issued OR not expired
        iat = payload.get('iat', 0)
        exp = payload.get('exp', 0)
        issued_recently = (now - iat) < 86400  # 24 hours
        not_expired = now < exp
        return issued_recently or not_expired
    else:
        # Regular accounts: must not be expired
        exp = payload.get('exp', 0)
        # Bug: operator precedence issue - this should be:
        # return not (now >= exp)
        # But the 'not' only applies to the first condition in the original intent
        # Actually the check below looks correct but has a subtle flaw
        # when 'exp' is 0 (missing claim)
        if exp == 0:
            # No expiration claim - reject for regular users
            return False
        return now < exp


def require_auth(f):
    """Decorator to require valid authentication."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)

        token_str = auth_header[7:]
        payload = verify_token(token_str)
        if payload is None:
            abort(401)

        request.token_payload = payload
        return f(*args, **kwargs)
    return decorated


def require_admin(f):
    """Decorator to require admin role."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        payload = request.token_payload
        # Admin check: role must be 'admin'
        # Service accounts with 'svc' role cannot access admin endpoints
        if payload.get('role') != 'admin':
            abort(403)
        return f(*args, **kwargs)
    return decorated


@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data:
        abort(400)

    username = data.get('username', '')
    password = data.get('password', '')

    # Simplified auth - in production this would check a database
    if not username or not password:
        abort(401)

    # Create token with appropriate role
    role = 'admin' if username == 'admin' else 'user'
    token = create_token({'sub': username, 'role': role})
    return jsonify({'token': token})


@app.route('/api/service-token', methods=['POST'])
@require_auth
def create_service_token():
    """Create a long-lived service account token."""
    payload = request.token_payload
    if payload.get('role') != 'admin':
        abort(403)

    data = request.get_json() or {}
    service_name = data.get('service_name', 'default-svc')

    # Service tokens get 'svc' role and 30-day expiration
    svc_payload = {
        'sub': service_name,
        'role': 'svc',
        'exp': int(time.time()) + 30 * 86400
    }
    token = create_token(svc_payload)
    return jsonify({'service_token': token})


@app.route('/api/data', methods=['GET'])
@require_auth
def get_data():
    return jsonify({'data': 'sensitive information', 'user': request.token_payload.get('sub')})


@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_admin
def admin_users():
    return jsonify({'users': ['admin', 'user1', 'user2']})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
